      "pr.ent.f4": "Fine-grained access control &amp; SSO",
      "pr.ent.f5": "Full audit trails &amp; compliance review",
      "pr.ent.f6": "Dedicated solutions architect",
      "pr.note": "All plans include native vector search, HTAP queries, and the unified Agent · Model · Data fabric. Usage-based billing is fully auditable.",
      "pr.s1.lbl": "Bill — not five separate vendors",
      "pr.s2.lbl": "Egress fees between layers",
      "pr.s3.lbl": "Free trial on the Team plan",
      "pr.s4.lbl": "Agents &amp; memory on paid plans",
      "pr.faq.eyebrow": "FAQ",
      "pr.faq.title": "Questions, answered",
      "pr.faq.q1": "Do I still need a separate vector database?",
      "pr.faq.a1": "No. Vector search is native to OmniFabric — embeddings live next to your relational data, so you run hybrid keyword + vector queries in a single statement, with no extra system to operate or pay for.",
      "pr.faq.q2": "How does usage-based billing work?",
      "pr.faq.a2": "You pay for storage, compute, and model calls you actually consume. Every charge maps to auditable usage records, so finance and engineering see exactly what drove the bill.",
      "pr.faq.q3": "Can I bring my own models?",
      "pr.faq.a3": "Yes. Route to any hosted LLM or embedding model through one API, or connect your own private endpoints. There's no lock-in — every call is wrapped in the same lineage and governance.",
      "pr.faq.q4": "Is OmniFabric available self-hosted?",
      "pr.faq.a4": "Enterprise plans support single-tenant cloud and fully self-hosted deployments, with multi-region data residency, SSO, and a dedicated solutions architect.",
      "pr.faq.q5": "What happens to my agents' memory if I roll back?",
      "pr.faq.a5": "Memory is versioned and fully audited. You can view memory as of any point in time and roll back safely — every write is traceable and reversible.",
      "pr.cta.title": "Ready to weave data and AI together?",
      "pr.cta.desc": "Spin up a free workspace, connect your first source, and ship a trusted agent today.",
      "pr.cta.b1": "Start building free",
      "pr.cta.b2": "Talk to sales",

