      "px.from": "低至",
      "px.inc": "<b>每个节点都内置完整的 智能体 · 模型 · 数据 fabric</b> —— 原生向量检索、HTAP 查询、治理、血缘与 SSO。没有任何能力被锁在更高档位，所有用量都计入可审计的记录。",
      "px.usd": "所有价格以美元计、不含当地税费。按小时用量按秒计费；包月节点为固定预留。",
      "px.faq.eb": "常见问题",
      "px.faq.h": "关于定价，逐一解答",
      "px.faq.q1": "包月还是按小时，该怎么选？",
      "px.faq.a1": "突发、短时或试验性的工作负载用按小时即用即付 —— 按秒计费、无需承诺。稳定的生产负载用包月预留，约省 20%。两者可在同一项目中混用，并可随时在两种方式间切换。",
      "px.faq.q2": "AI 的 token 怎么计费？",
      "px.faq.a2": "每次模型调用都按输入和输出 token 计量，并以百万为单位计价。可使用 OmniFabric 路由的模型，也可使用你自己的厂商密钥 —— 此时 token 按厂商成本透传、不加价，同时仍纳入统一的血缘与治理。",
      "px.faq.q3": "不同区域价格会不一样吗？",
      "px.faq.a3": "七个区域的标准定价一致。你的数据只在所选区域内处理与存储。如需在特定区域承诺用量或大规模使用，请联系销售获取定制报价。",
      "px.faq.q4": "有没有免费的起步方式？",
      "px.faq.a4": "有 —— 免费创建工作区、接入数据源并上线第一个智能体。只有当你开通算力节点，或产生按量计费的 AI、存储或出站流量时，才开始付费。",
      "px.faq.q5": "存储和出站流量分别指什么？",
      "px.faq.a5": "存储是你留在 fabric 中的数据 —— 表、向量与文件 —— 按 GB·月计费。出站流量是离开本区域、流向公网的流量。读取自有数据以及区域内的流量都免费。",
      "px.cta.h": "免费开始，准备好了再扩展",
      "px.cta.p": "先创建工作区、按小时开通第一个节点，等进入生产再转为包月。",
