      "sov.h.h": "你的数据与 AI,始终在你掌控之中",
      "sov.h.p": "面向受监管与关键业务负载,OmniFabric 部署在你的数据必须驻留之处——你的区域、你的基础设施、你的规则。内建完整的数据驻留、部署灵活性与端到端治理。",
