      "au.sso.secured": "Sécurisé par l'authentification unique CloudSigma",
      "au.sso.h": "Connectez-vous à OmniFabric",
      "au.sso.sub": "OmniFabric utilise votre compte CloudSigma. Continuez avec l'authentification unique — une identité sécurisée et souveraine pour vos données, modèles et agents.",
      "au.sso.login": "Continuer avec CloudSigma",
