      "au.sso.create": "Créer un compte CloudSigma",
      "au.sso.note": "Vous serez redirigé en toute sécurité vers CloudSigma pour vous connecter. En continuant, vous acceptez notre politique de confidentialité et nos conditions d'utilisation.",
      "px.eyebrow": "Tarifs",
      "px.title": "Payez ce que vous utilisez — à l'heure ou au mois",
      "px.desc": "Achetez des nœuds de calcul à l'heure en paiement à l'usage, ou réservez-les au mois, puis ajoutez l'IA, le stockage et le trafic sortant à l'usage. Transparent, détaillé sur une seule facture, et disponible dans chaque région OmniFabric.",
      "px.reg.eb": "Régions",
      "px.reg.h": "Disponible dans chaque région",
      "px.reg.p": "Déployez OmniFabric au plus près de vos utilisateurs et de vos régulateurs. Vos données sont traitées et stockées uniquement dans la région choisie. Les tarifs catalogue sont identiques d'une région à l'autre — contactez le service commercial pour un engagement ou un volume.",
      "px.reg.in": "Déploiement dans",
      "px.reg.stay": "vos données restent dans la région",
      "px.cn.eb": "Nœuds de calcul",
      "px.cn.h": "Achetez du calcul à l'heure ou au mois",
      "px.cn.p": "Du calcul vendu au nœud qui alimente tout le fabric — données, modèles et agents. Absorbez les pics en paiement à l'usage, ou réservez des nœuds au mois et économisez.",
      "px.cn.note": "Les nœuds à l'heure sont facturés à la seconde, sans engagement — idéal pour les pics, le batch et le dev. Les nœuds au mois sont une réservation forfaitaire, environ 20 % moins chère. Le stockage et les données sont découplés du calcul : redimensionnez vos nœuds à tout moment sans perdre l'état.",
      "px.cn.cta": "Commencer",
