      "px.st.lab": "Tous types de données",
      "px.st.u": "/ Go-mois",
      "px.eg.t": "Trafic sortant",
      "px.eg.p": "Transfert de données sortant de votre région vers l'Internet public. Le trafic entrant et intra-région est toujours gratuit.",
      "px.eg.lab": "Transfert sortant",
      "px.eg.u": "/ Go",
      "px.eg.free": "100 Go / mois gratuits",
      "px.from": "dès",
      "px.inc": "<b>Chaque nœud embarque l'intégralité du fabric Agent · Modèle · Données</b> — recherche vectorielle native, requêtes HTAP, gouvernance, traçabilité et SSO. Rien n'est réservé à un palier supérieur, et tout l'usage est mesuré dans des enregistrements auditables.",
      "px.usd": "Tous les prix sont en USD, hors taxes locales. L'usage horaire est facturé à la seconde ; les nœuds mensuels sont une réservation fixe.",
      "px.faq.eb": "FAQ",
      "px.faq.h": "Vos questions de tarification, élucidées",
      "px.faq.q1": "Mensuel ou horaire — que choisir ?",
      "px.faq.a1": "Utilisez le paiement à l'usage horaire pour les charges en pic, éphémères ou expérimentales — facturé à la seconde, sans engagement. Réservez des nœuds au mois pour une production stable et économisez environ 20 %. Vous pouvez combiner les deux dans un même projet et basculer un nœud de l'un à l'autre à tout moment.",
      "px.faq.q2": "Comment les tokens d'IA sont-ils facturés ?",
      "px.faq.a2": "Chaque appel de modèle est mesuré en tokens d'entrée et de sortie, facturé au million. Utilisez les modèles routés par OmniFabric, ou vos propres clés fournisseur — les tokens sont alors reportés au coût du fournisseur sans marge, tout en restant couverts par la même traçabilité et gouvernance.",
      "px.faq.q3": "Les tarifs varient-ils selon la région ?",
      "px.faq.a3": "Les tarifs catalogue sont identiques dans les sept régions. Vos données sont traitées et stockées uniquement dans la région choisie. Pour un engagement ou un fort volume dans une région donnée, contactez le service commercial pour un devis sur mesure.",
      "px.faq.q4": "Existe-t-il un moyen de démarrer gratuitement ?",
      "px.faq.a4": "Oui — créez un espace de travail gratuitement, connectez une source et déployez un premier agent. Vous ne payez qu'à partir du moment où vous provisionnez un nœud de calcul ou consommez de l'IA, du stockage ou du trafic sortant mesurés.",
      "px.faq.q5": "Qu'entend-on par stockage et trafic sortant ?",
      "px.faq.a5": "Le stockage correspond aux données que vous conservez dans le fabric — tables, vecteurs et fichiers — facturées au Go-mois. Le trafic sortant est le trafic quittant la région vers l'Internet public. La lecture de vos propres données et le trafic intra-région sont gratuits.",
      "px.cta.h": "Commencez gratuitement, passez à l'échelle quand vous êtes prêt",
      "px.cta.p": "Lancez un espace de travail, provisionnez votre premier nœud à l'heure, et ne vous engagez au mois qu'une fois en production.",
