      "p.ov.eb": "Plateforme Data + IA tout-en-un",
      "p.ov.h": "Une plateforme, de la donnée brute aux applications intelligentes",
      "p.ov.p": "OmniFabric Intelligence offre des capacités de bout en bout, de l'ingestion multi-sources aux applications intelligentes — gouvernance et traitement unifiés des bases de données, données structurées, documents, images, audio et vidéo. Intégration, nettoyage, vectorisation et orchestration intégrés transforment la donnée brute en actifs prêts pour la BI, l'Agentic RAG, le fine-tuning et la recherche multimodale.",
