      "p.eng.p": "Quatre moteurs fonctionnent comme une seule plateforme — un socle d'intelligence de données multimodal unifié et de niveau entreprise.",
      "p.eng1.s": "Base de données cloud-native hyperconvergée",
      "p.eng1.d": "Unifie OLTP et OLAP, vecteur et recherche, lakehouse, données structurées et non structurées — un socle de données multimodal d'entreprise.",
      "p.eng2.s": "Référentiel de services de modèles IA",
      "p.eng2.d": "Gestion centralisée de modèles IA multi-types et multi-specs — simplifie l'intégration et la maintenance pour des applications intelligentes agiles.",
      "p.eng3.s": "Pipeline ETL de données multimodales",
      "p.eng3.d": "Des connecteurs dédiés pour une ingestion et une transformation multimodales unifiées, avec orchestration visuelle de bout en bout pour un traitement en flux efficace.",
      "p.eng4.s": "Agent d'intelligence des données",
      "p.eng4.d": "Des agents de recherche et d'ingénierie de données pour données hétérogènes — l'utilisateur libère la valeur des données en langage naturel.",
      "p.cm.eb": "Quatre modules clés",
      "p.cm.h": "Toute la chaîne, de bout en bout",
      "p.cm.p": "De l'ingestion aux agents de recherche — la plateforme d'intelligence de données multimodale de nouvelle génération.",
      "p.cm1.t": "Ingestion, stockage et indexation unifiés",
      "p.cm1.f1": "<b>Intégration des sources</b> — connecteurs multi-sources pour données structurées, semi-structurées et non structurées.",
      "p.cm1.f2": "<b>Ingestion automatisée</b> — chargements historiques et incrémentaux, complets et en temps réel.",
      "p.cm2.t": "Analyse et extraction multimodales",
      "p.cm2.f1": "<b>Analyse de documents complexes</b> — extraction d'informations structurées via plusieurs stratégies d'analyse, de découpage et de vectorisation.",
      "p.cm2.f2": "<b>Analyse multimédia</b> — images, audio et vidéo avec modèles interchangeables.",
      "p.cm3.t": "Workflows de traitement flexibles",
      "p.cm3.f1": "<b>Opérateurs intégrés</b> — nœuds prêts à l'emploi d'analyse, nettoyage et augmentation, plus nœuds personnalisés.",
      "p.cm3.f2": "<b>Orchestration visuelle</b> — configuration de workflows basée sur des DAG pour un montage rapide.",
      "p.cm4.t": "Agents de recherche et d'analyse",
      "p.cm4.f1": "<b>Agent de Q&amp;R</b> — requêtes en langage naturel sur données structurées et non structurées, avec agrégation et exploration.",
      "p.cm4.f2": "<b>Traçabilité de bout en bout</b> — les réponses incluent la lignée complète des sources, du raisonnement et des étapes d'exécution.",
