      "ab.cs.f3v": "75 000+",
      "ab.cs.f4l": "Présence",
      "ab.cs.f4v": "Zurich · Las Vegas · Washington",
      "ab.cs.link": "Visiter cloudsigma.com",
      "ab.mo.tag": "Héritage data &amp; IA",
      "ab.mo.name": "MatrixOrigin",
      "ab.mo.title": "Une plateforme d’intelligence des données AI-native",
      "ab.mo.p1": "Fondée en 2021 avec des équipes à Shanghai, Shenzhen, Pékin et dans la Bay Area, MatrixOrigin développe MatrixOne — une base HTAP AI-native, compatible MySQL, dotée du versionnage Git-for-Data et d’une recherche vectorielle et plein texte intégrée.",
      "ab.mo.p2": "Son moteur hyper-convergé unifie les charges transactionnelles, analytiques, vectorielles et plein texte dans un seul système — sans ETL — couplé à MatrixOne Intelligence, une plateforme Data + IA tout-en-un.",
      "ab.mo.f1l": "Fondée",
      "ab.mo.f1v": "2021",
