      "hero.badge.text": "Le runtime d’agents et la mémoire longue durée sont désormais en disponibilité générale",
      "hero.title": "Maîtrisez vos données.<br><span class=\"grad\">Propulsez votre IA.</span>",
      "hero.lead": "OmniFabric unifie vos données, modèles et agents sur une seule plateforme — chaque décision d’IA s’appuie ainsi sur des données fiables, gouvernées et en temps réel, plutôt que sur des copies obsolètes.",
