      "pillars.title": "Agents, modèles et données sur une plateforme unifiée",
      "pillars.desc": "La plupart des équipes greffent une base vectorielle, une passerelle de modèles et une couche d’orchestration sur une base héritée. OmniFabric consolide le tout dans une plateforme hyperconvergée unique, où chaque couche renforce les autres.",
