      "cust.cta.desc": "Commencez gratuitement, ou parlez de votre cas d’usage à notre équipe.",
      "case1.challenge": "Modèles et caractéristiques étaient reconstruits en silos, ralentissant chaque projet et gonflant les coûts de calcul.",
      "case1.solution": "Une plateforme de caractéristiques multimodales sur OmniFabric a permis de publier, découvrir et réutiliser caractéristiques et embeddings depuis un magasin gouverné.",
      "case1.results": "La réutilisation inter-équipes a progressé de 40 % et les cycles de développement de modèles ont diminué de 30 %.",
      "case2.challenge": "Les données urbaines couvraient des dizaines de formats et systèmes incompatibles, bloquant l’automatisation de la ville intelligente.",
      "case2.solution": "OmniFabric Intelligence a ingéré et corrélé les données urbaines multimodales en un corpus unique, gouverné et interrogeable.",
      "case2.results": "Un corpus unifié a alimenté de nouvelles applications avec une automatisation environ 5× plus rapide.",
      "case3.challenge": "Les équipes marketing passaient plus de temps à assembler des données qu’à mener des campagnes.",
      "case3.solution": "Un copilote marketing fondé sur un socle de données d’agent unifié, avec mémoire sur chaque campagne.",
      "case3.results": "L’efficacité marketing s’est améliorée de plus de 50 %.",
      "case4.challenge": "Les appels d’offres à fort enjeu exigeaient de réconcilier des données de multiples sources cloisonnées dans des délais serrés.",
