      "case4.results": "L’efficacité des décisions d’appel d’offres a progressé de 40 %.",
      "case5.challenge": "Les analystes passaient l’essentiel de leur temps à collecter des données sur 60+ sources au lieu d’analyser.",
      "case5.solution": "Un système de recherche automatisé sur OmniFabric a unifié ces sources et rédigé des analyses sourcées.",
