      "pr.faq.eyebrow": "FAQ",
      "pr.faq.title": "Vos questions, nos réponses",
      "pr.faq.q1": "Ai-je encore besoin d’une base vectorielle séparée ?",
      "pr.faq.a1": "Non. La recherche vectorielle est native à OmniFabric — les embeddings vivent près de vos données relationnelles, donc vous lancez des requêtes hybrides mots-clés + vecteurs en une seule instruction, sans système supplémentaire à exploiter ou payer.",
      "pr.faq.q2": "Comment fonctionne la facturation à l’usage ?",
      "pr.faq.a2": "Vous payez le stockage, le calcul et les appels de modèles réellement consommés. Chaque coût correspond à des relevés d’usage auditables, finance et ingénierie voient exactement l’origine de la facture.",
      "pr.faq.q3": "Puis-je apporter mes propres modèles ?",
      "pr.faq.a3": "Oui. Routez vers tout LLM ou modèle d’embedding hébergé via une seule API, ou connectez vos propres points de terminaison privés. Aucun verrouillage — chaque appel suit la même traçabilité et gouvernance.",
      "pr.faq.q4": "OmniFabric est-il disponible en auto-hébergement ?",
      "pr.faq.a4": "Les plans Entreprise prennent en charge le cloud mono-locataire et le déploiement entièrement auto-hébergé, avec résidence multi-région, SSO et architecte solutions dédié.",
