      "au.sso.secured": "Protegido por el inicio de sesión único de CloudSigma",
      "au.sso.h": "Inicia sesión en OmniFabric",
      "au.sso.sub": "OmniFabric usa tu cuenta de CloudSigma. Continúa con el inicio de sesión único — una identidad segura y soberana para datos, modelos y agentes.",
      "au.sso.login": "Continuar con CloudSigma",
      "au.sso.new": "¿Nuevo en CloudSigma?",
      "au.sso.create": "Crear una cuenta de CloudSigma",
      "au.sso.note": "Te redirigiremos de forma segura a CloudSigma para iniciar sesión. Al continuar, aceptas nuestra Política de Privacidad y Términos del Servicio.",
      "px.eyebrow": "Precios",
      "px.title": "Paga por lo que usas — por hora o por mes",
      "px.desc": "Compra nodos de cómputo por hora con pago por uso, o resérvalos por mes, y añade IA, almacenamiento y tráfico de salida por consumo. Transparente, detallado en una sola factura y disponible en todas las regiones de OmniFabric.",
      "px.reg.eb": "Regiones",
      "px.reg.h": "Disponible en todas las regiones",
      "px.reg.p": "Despliega OmniFabric cerca de tus usuarios y tus reguladores. Tus datos se procesan y almacenan solo en la región que elijas. El precio de lista es el mismo en todas las regiones — habla con ventas para uso comprometido y volúmenes.",
      "px.reg.in": "Desplegando en",
      "px.reg.stay": "tus datos permanecen en la región",
      "px.cn.eb": "Nodos de cómputo",
      "px.cn.h": "Compra cómputo por hora o por mes",
      "px.cn.p": "Cómputo vendido por nodo que impulsa todo el fabric — datos, modelos y agentes. Absorbe los picos con pago por uso, o reserva nodos por mes y ahorra.",
      "px.cn.note": "Los nodos por hora se facturan por segundo y sin compromiso — ideales para picos, lotes y desarrollo. Los nodos mensuales son una reserva fija y cuestan alrededor de un 20 % menos. El almacenamiento y los datos están desacoplados del cómputo, así que puedes escalar nodos en cualquier momento sin perder el estado.",
      "px.cn.cta": "Empezar",
      "px.t.mo": "Mensual · reservado",
      "px.t.hr": "Por hora · pago por uso",
      "px.save": "Ahorra ~20 %",
      "px.feat": "El más popular",
      "px.n1": "Starter",
      "px.n2": "Estándar",
      "px.n3": "Rendimiento",
      "px.n4": "GPU",
      "px.spec.ssd": "Almacenamiento NVMe SSD",
      "px.spec.gpu": "1 acelerador GPU",
      "px.use.eb": "Por consumo",
      "px.use.h": "Paga solo por lo que usas",
      "px.use.p": "Además del cómputo, tres servicios medidos — facturados puramente por consumo y detallados en la misma factura.",
      "px.ai.t": "Servicios de IA",
      "px.ai.p": "Conecta con más de 100 modelos alojados — chat, embeddings y rerankers — a través de una sola API. Se factura por millón de tokens; usa tus propias claves de proveedor para repercutir el coste.",
      "px.ai.in": "Tokens de entrada",
      "px.ai.out": "Tokens de salida",
      "px.ai.u": "/ 1M tokens",
      "px.st.t": "Almacenamiento",
      "px.st.p": "Un almacén unificado para datos relacionales, vectoriales y multimodales. Compresión y niveles incluidos; leer tus propios datos siempre es gratis.",
      "px.st.lab": "Todos los tipos de datos",
      "px.st.u": "/ GB-mes",
      "px.eg.t": "Tráfico de salida",
      "px.eg.p": "Transferencia de datos saliente de tu región hacia la Internet pública. El tráfico entrante y dentro de la región siempre es gratis.",
      "px.eg.lab": "Transferencia saliente",
      "px.eg.u": "/ GB",
      "px.eg.free": "Primeros 100 GB / mes gratis",
      "px.from": "desde",
      "px.inc": "<b>Cada nodo incluye el fabric completo de Agente · Modelo · Datos</b> — búsqueda vectorial nativa, consultas HTAP, gobernanza, linaje y SSO. Nada queda detrás de un nivel superior, y todo el uso se mide en registros auditables.",
      "px.usd": "Todos los precios en USD y sin impuestos locales. El uso por hora se factura por segundo; los nodos mensuales son una reserva fija.",
      "px.faq.eb": "Preguntas frecuentes",
      "px.faq.h": "Tus dudas de precios, resueltas",
      "px.faq.q1": "¿Mensual o por hora — cuál elegir?",
      "px.faq.a1": "Usa el pago por uso por hora para cargas con picos, efímeras o experimentales — se factura por segundo y sin compromiso. Reserva nodos mensuales para producción estable y ahorra alrededor de un 20 %. Puedes combinar ambos en el mismo proyecto y cambiar un nodo de uno a otro en cualquier momento.",
      "px.faq.q2": "¿Cómo se facturan los tokens de IA?",
      "px.faq.a2": "Cada llamada al modelo se mide por tokens de entrada y salida y se cobra por millón. Usa los modelos enrutados por OmniFabric o tus propias claves de proveedor — en cuyo caso los tokens se repercuten al coste del proveedor sin recargo, manteniéndose bajo el mismo linaje y gobernanza.",
      "px.faq.q3": "¿El precio cambia según la región?",
      "px.faq.a3": "El precio de lista es el mismo en las siete regiones. Tus datos se procesan y almacenan solo en la región que elijas. Para uso comprometido o gran volumen en una región concreta, habla con ventas para un presupuesto a medida.",
      "px.faq.q4": "¿Hay una forma gratuita de empezar?",
      "px.faq.a4": "Sí — crea un espacio de trabajo gratis, conecta una fuente y lanza un primer agente. Solo empiezas a pagar cuando aprovisionas un nodo de cómputo o consumes IA, almacenamiento o tráfico de salida medidos.",
      "px.faq.q5": "¿Qué cuenta como almacenamiento y salida?",
      "px.faq.a5": "El almacenamiento son los datos que guardas en el fabric — tablas, vectores y archivos — facturados por GB-mes. La salida es el tráfico que abandona la región hacia la Internet pública. Leer tus propios datos y el tráfico dentro de la región son gratis.",
      "px.cta.h": "Empieza gratis y escala cuando estés listo",
      "px.cta.p": "Lanza un espacio de trabajo, aprovisiona tu primer nodo por hora y comprométete al mes solo cuando estés en producción.",
