      "nav.demo": "Demos",
      "demo.eb": "Demos en vivo",
      "demo.h": "OmniFabric en acción",
      "demo.p": "Diez de los casos de uso de Data + IA más comunes, cada uno animado de extremo a extremo y todos impulsados por la misma fabric.",
      "demo.c1.t": "Panel de analítica",
      "demo.c1.d": "KPIs y gráficos en vivo que se actualizan en cuanto llegan los datos.",
      "demo.c2.t": "Mantenimiento predictivo",
      "demo.c2.d": "Las tendencias de sensores anticipan fallos y generan una orden de trabajo.",
      "demo.c3.t": "Insights en lenguaje natural",
      "demo.c3.d": "Pregunta en lenguaje natural y obtén el gráfico y la respuesta.",
      "demo.c4.t": "Chatbot de manual de producto",
