      "p.out3": "Analítica de datos inteligente",
      "p.out4": "Entrenamiento de modelos de IA",
      "p.eng.eb": "Bajo el capó",
      "p.eng.h": "Cuatro motores que impulsan la fabric",
      "p.eng.p": "Cuatro motores funcionan como una sola plataforma: una base de inteligencia de datos multimodal unificada y de nivel empresarial.",
      "p.eng1.s": "Base de datos cloud-native hiperconvergente",
      "p.eng1.d": "Unifica OLTP y OLAP, vector y búsqueda, lakehouse, datos estructurados y no estructurados: una base de datos multimodal empresarial.",
      "p.eng2.s": "Repositorio de servicios de modelos de IA",
      "p.eng2.d": "Gestión centralizada de modelos de IA de varios tipos y especificaciones: simplifica la incorporación y el mantenimiento para aplicaciones inteligentes ágiles.",
      "p.eng3.s": "Pipeline ETL de datos multimodales",
      "p.eng3.d": "Conectores específicos para ingesta y transformación multimodal unificada, con orquestación visual de extremo a extremo para un procesamiento en streaming eficiente.",
      "p.eng4.s": "Agente de inteligencia de datos",
      "p.eng4.d": "Agentes de búsqueda e ingeniería de datos para datos heterogéneos: el usuario libera el valor de los datos con lenguaje natural.",
      "p.cm.eb": "Cuatro módulos clave",
      "p.cm.h": "Todo el flujo, de extremo a extremo",
      "p.cm.p": "De la ingesta a los agentes de recuperación: la plataforma de inteligencia de datos multimodal de nueva generación.",
      "p.cm1.t": "Ingesta, almacenamiento e indexación unificados",
      "p.cm1.f1": "<b>Integración de fuentes</b> — conectores multifuente para datos estructurados, semiestructurados y no estructurados.",
      "p.cm1.f2": "<b>Ingesta automatizada</b> — cargas históricas e incrementales, completas y en tiempo real.",
      "p.cm2.t": "Análisis y extracción multimodal",
      "p.cm2.f1": "<b>Análisis de documentos complejos</b> — extrae información estructurada con varias estrategias de análisis, fragmentación y vectorización.",
      "p.cm2.f2": "<b>Análisis multimedia</b> — imágenes, audio y vídeo con modelos intercambiables.",
      "p.cm3.t": "Flujos de procesamiento flexibles",
      "p.cm3.f1": "<b>Operadores integrados</b> — nodos listos de análisis, limpieza y aumento, además de nodos personalizados.",
      "p.cm3.f2": "<b>Orquestación visual</b> — configuración de workflows basada en DAG para montar pipelines rápido.",
      "p.cm4.t": "Agentes de recuperación y análisis",
      "p.cm4.f1": "<b>Agente de preguntas y respuestas</b> — consultas en lenguaje natural sobre datos estructurados y no estructurados, con agregación y drill-down.",
      "p.cm4.f2": "<b>Trazabilidad de extremo a extremo</b> — las respuestas incluyen el linaje completo de fuentes, razonamiento y pasos de ejecución.",
      "p.sec.eb": "Nivel empresarial",
      "p.sec.h": "Seguridad y control de acceso integrados",
      "p.sec1.t": "Control de acceso RBAC",
      "p.sec1.d": "Gestión granular de usuarios, roles, permisos y acceso a datos, hasta el nivel de columna.",
      "p.sec2.t": "Aislamiento multiinquilino",
      "p.sec2.d": "Inquilinos de espacio de trabajo aislados con almacenamiento y cómputo dedicados, para que equipos y datos nunca crucen fronteras.",
      "p.sec3.t": "Linaje y registros de auditoría",
      "p.sec3.d": "Cada transformación y decisión del agente es trazable de extremo a extremo: listo para auditorías de GDPR, SOC 2 y tus propias políticas.",
      "p.dep.eb": "Despliega a tu manera",
      "p.dep.h": "Despliegue privado o nube gestionada",
      "p.dep1.t": "Despliegue privado",
      "p.dep1.f1": "Entorno privado aislado: datos totalmente bajo tu control.",
      "p.dep1.f2": "Red privada de alto rendimiento, sin latencia de internet público.",
      "p.dep1.f3": "Despliegue único, uso prolongado, coste predecible.",
      "p.dep1.cta": "Contáctanos",
