      "nav.product": "Producto",
      "prod.eyebrow": "La plataforma",
      "prod.title": "Una fabric hiperconvergente para datos, modelos y agentes",
      "prod.desc": "Todo lo que OmniFabric reúne: una base de datos nativa en la nube, inteligencia multimodal, un runtime de agentes confiable, memoria a largo plazo y regiones soberanas que tú controlas.",
      "nav.capabilities": "Capacidades",
