      "hero.badge.pill": "NUEVO",
      "hero.badge.text": "El runtime de agentes y la memoria de largo plazo ya están en disponibilidad general",
      "hero.title": "Controla tus datos.<br><span class=\"grad\">Impulsa tu IA.</span>",
      "hero.lead": "OmniFabric unifica tus datos, modelos y agentes en una sola plataforma — para que cada decisión de IA se ejecute sobre datos fiables, gobernados y en tiempo real, no sobre copias obsoletas.",
      "hero.cta1": "Empezar gratis",
      "hero.cta2": "Explorar la plataforma",
      "hero.trust": "La confianza de equipos de datos e IA que ejecutan agentes en producción",
      "fw.sub": "Inteligencia",
      "fw.title": "Volante",
      "node.agent": "Agente",
      "node.model": "Modelo",
      "node.data": "Datos",
      "hero.float1": "Búsqueda vectorial nativa",
      "hero.float2": "Linaje de decisiones registrado",
      "logos.title": "Un solo tejido para el stack moderno de datos e IA",
      "pillars.eyebrow": "El volante de inteligencia",
      "pillars.title": "Agentes, modelos y datos en una plataforma unificada",
      "pillars.desc": "La mayoría de los equipos acoplan una base vectorial, una pasarela de modelos y una capa de orquestación sobre una base heredada. OmniFabric lo consolida todo en una única plataforma hiperconvergida, donde cada capa refuerza a las demás.",
      "pillar1.tag": "Capa de datos",
      "pillar1.title": "Una única fuente de verdad",
      "pillar1.desc": "Un motor cloud-native e hiperconvergido que ejecuta cargas transaccionales y analíticas juntas, con vectores integrados — sin proliferación de ETL ni réplicas obsoletas.",
      "pillar2.tag": "Capa de modelos",
      "pillar2.title": "Cualquier modelo, totalmente gobernado",
      "pillar2.desc": "Llama a cualquier LLM o modelo de embeddings desde una sola interfaz, con una instantánea de contexto y linaje de extremo a extremo en cada solicitud.",
      "pillar3.tag": "Capa de agentes",
      "pillar3.title": "Agentes que mejoran en producción",
      "pillar3.desc": "Los agentes en producción aprenden del feedback real, conservan memoria de largo plazo y se automejoran tras controles de regresión — de forma segura.",
      "stat1.lbl": "Tejido unificado — BD, vectores, modelos &amp; agentes",
      "stat2.lbl": "Modelos accesibles a través de una sola API",
      "stat3.lbl": "bases de datos vectoriales aparte que mantener",
      "stat4.lbl": "Disponibilidad con almacenamiento desacoplado",
      "cap.eyebrow": "Capacidades de la plataforma",
      "cap.title": "Una plataforma de datos diseñada para la era de los agentes",
      "cap.desc": "Todo lo necesario para llevar tus aplicaciones de IA del prototipo a producción — sin integrar tú mismo media docena de sistemas.",
      "cap1.eyebrow": "OmniFabric Core · Plataforma de datos",
      "cap1.title": "Una base hiperconvergida y cloud-native",
      "cap1.desc": "Un único motor para cargas transaccionales y analíticas, con almacenamiento y cómputo desacoplados para escalar de forma independiente y bajo demanda.",
      "cap1.li1": "<b>HTAP en un solo motor</b> — sirve OLTP y OLAP desde los mismos datos, sin pipelines que sincronizar.",
      "cap1.li2": "<b>Almacenamiento y cómputo desacoplados</b> — escala el rendimiento de consultas y la capacidad por separado.",
      "cap1.li3": "<b>Búsqueda vectorial y ML integrados</b> — embeddings e inferencia junto a tus datos.",
      "cap1.li4": "<b>Clonado sin copia y time travel</b> — ramifica y revierte conjuntos de datos al instante.",
      "cap1.link": "Explorar OmniFabric Core",
      "cap2.eyebrow": "OmniFabric Intelligence · Multimodal",
      "cap2.title": "Convierte cualquier dato en contexto listo para IA",
      "cap2.desc": "Ingiere fuentes estructuradas, semiestructuradas y no estructuradas, y luego analízalas, extrae y enlázalas en una base de conocimiento que se actualiza continuamente.",
      "cap2.li1": "<b>Ingesta unificada</b> — bases de datos, archivos, APIs y streams en una sola plataforma.",
      "cap2.li2": "<b>Procesamiento multimodal</b> — PDFs, imágenes y vídeo se analizan y vectorizan automáticamente.",
      "cap2.li3": "<b>Grafos de conocimiento</b> — enlaces semánticos conectan entidades entre todas las fuentes.",
      "cap2.li4": "<b>Extracción automatizada</b> — comprensión de documentos siempre actualizada.",
      "cap2.link": "Ver pipelines multimodales",
      "flow.ingest.t": "Ingerir",
      "flow.ingest.s": "PDF · imagen · vídeo · tablas · flujos",
      "flow.parse.t": "Analizar &amp; vectorizar",
      "flow.parse.s": "extracción · fragmentación · vectores",
      "flow.kb.t": "Base de conocimiento",
      "flow.kb.s": "enlazada semánticamente &amp; consultable",
      "cap3.eyebrow": "OmniFabric Agent · Runtime de IA",
      "cap3.title": "Lanza agentes en los que puedes confiar en producción",
      "cap3.desc": "Un runtime de agentes que captura una instantánea de contexto completa antes de cada llamada al modelo, para decisiones explicables, comprobables y reversibles.",
      "cap3.li1": "<b>Linaje de decisiones auditable</b> — contexto completo capturado antes de cada llamada al modelo.",
      "cap3.li2": "<b>Automejora</b> — los prompts y las skills se actualizan automáticamente con el feedback real.",
