      "pr.faq.eyebrow": "Preguntas frecuentes",
      "pr.faq.title": "Tus preguntas, respondidas",
      "pr.faq.q1": "¿Sigo necesitando una base vectorial aparte?",
      "pr.faq.a1": "No. La búsqueda vectorial es nativa en OmniFabric — los embeddings viven junto a tus datos relacionales, así que ejecutas consultas híbridas de palabras clave + vectores en una sola sentencia, sin un sistema extra que operar o pagar.",
      "pr.faq.q2": "¿Cómo funciona la facturación por uso?",
      "pr.faq.a2": "Pagas por el almacenamiento, el cómputo y las llamadas a modelos que realmente consumes. Cada cargo corresponde a registros de uso auditables, así finanzas e ingeniería ven exactamente qué generó la factura.",
      "pr.faq.q3": "¿Puedo usar mis propios modelos?",
      "pr.faq.a3": "Sí. Enruta a cualquier LLM o modelo de embeddings alojado vía una API, o conecta tus propios endpoints privados. Sin bloqueo — cada llamada sigue el mismo linaje y gobernanza.",
      "pr.faq.q4": "¿OmniFabric está disponible autoalojado?",
      "pr.faq.a4": "Los planes Empresa admiten nube de inquilino único y despliegue totalmente autoalojado, con residencia de datos multirregión, SSO y arquitecto de soluciones dedicado.",
      "pr.faq.q5": "¿Qué pasa con la memoria de mis agentes si revierto?",
      "pr.faq.a5": "La memoria está versionada y totalmente auditada. Puedes verla en cualquier punto del tiempo y revertir con seguridad — cada escritura es rastreable y reversible.",
