      "px.desc": "اشترِ عُقد حوسبة بالساعة بنظام الدفع حسب الاستخدام، أو احجزها شهريًا، ثم أضف خدمات الذكاء الاصطناعي والتخزين وحركة البيانات الصادرة حسب الاستهلاك. شفافة، ومفصّلة في فاتورة واحدة، ومتاحة في كل منطقة من مناطق OmniFabric.",
