      "px.reg.p": "شغّل OmniFabric قرب مستخدميك وجهاتك التنظيمية. تُعالَج بياناتك وتُخزَّن فقط في المنطقة التي تختارها. أسعار القائمة موحّدة بين المناطق — تواصل مع المبيعات للحصول على عروض الالتزام والحجم.",
