      "p.hero.h": "من البيانات إلى الذكاء، ومن الذكاء إلى الفعل",
      "p.hero.p": "منصة Data + AI متكاملة — من استيعاب البيانات متعددة المصادر إلى التطبيقات الذكية في الإنتاج، تغطّي المسار الكامل على أساس واحد.",
