      "p.eng1.s": "قاعدة بيانات سحابية أصلية فائقة التقارب",
      "p.eng1.d": "توحّد OLTP وOLAP، والمتجهات والبحث، والـ lakehouse، والبيانات المنظّمة وغير المنظّمة — أساس بيانات متعدد الوسائط بمستوى المؤسسات.",
