      "p.cm1.t": "استيعاب وتخزين وفهرسة موحّدة",
      "p.cm1.f1": "<b>تكامل مصادر البيانات</b> — موصّلات متعددة المصادر للبيانات المنظّمة وشبه المنظّمة وغير المنظّمة.",
      "p.cm1.f2": "<b>استيعاب آلي</b> — تحميل تاريخي وتزايدي مع اكتمال وحداثة فورية.",
      "p.cm2.t": "تحليل واستخراج متعدد الوسائط",
      "p.cm2.f1": "<b>تحليل المستندات المعقّدة</b> — استخراج معلومات منظّمة عبر استراتيجيات متعددة للتحليل والتقسيم والتوجيه المتجهي.",
      "p.cm2.f2": "<b>تحليل الوسائط المتعددة</b> — صور وصوت وفيديو مع دعم نماذج قابلة للتبديل.",
      "p.cm3.t": "تدفّقات معالجة بيانات مرنة",
      "p.cm3.f1": "<b>عوامل تشغيل مدمجة</b> — عُقد جاهزة للتحليل والتنظيف والإثراء، مع دعم العُقد المخصّصة.",
