      "p.cm4.t": "وكلاء استرجاع وتحليل البيانات",
      "p.cm4.f1": "<b>وكيل أسئلة وأجوبة البيانات</b> — استعلامات باللغة الطبيعية عبر البيانات المنظّمة وغير المنظّمة، مع تجميع وتعمّق.",
      "p.cm4.f2": "<b>تتبّع كامل للسلسلة</b> — تتضمّن الإجابات نسبًا كاملًا للمصادر والاستدلال وخطوات التنفيذ.",
