      "hero.badge.pill": "جديد",
      "hero.badge.text": "أصبح زمن تشغيل الوكلاء والذاكرة طويلة المدى متاحَين للجميع (GA)",
      "hero.title": "تحكّم في بياناتك.<br><span class=\"grad\">عزّز ذكاءك الاصطناعي.</span>",
      "hero.lead": "يوحّد OmniFabric بياناتك ونماذجك ووكلاءك على منصة واحدة — لتعمل كل قرارات الذكاء الاصطناعي على بيانات موثوقة ومحوكمة وفورية بدل النسخ القديمة.",
