      "logos.title": "نسيج واحد لمنظومة البيانات والذكاء الاصطناعي الحديثة",
      "pillars.eyebrow": "دولاب موازنة الذكاء",
      "pillars.title": "الوكلاء والنماذج والبيانات على منصة موحّدة واحدة",
      "pillars.desc": "تلجأ معظم الفرق إلى إلحاق قاعدة متجهات وبوابة نماذج وطبقة تنسيق بقاعدة بيانات قديمة. يدمج OmniFabric ذلك كله في منصة واحدة فائقة الدمج، فتعزّز كل طبقة الأخرى.",
      "pillar1.tag": "طبقة البيانات",
      "pillar1.title": "مصدر واحد للحقيقة",
      "pillar1.desc": "محرّك سحابي أصيل فائق الدمج يشغّل الأحمال المعامِلاتية والتحليلية معًا، مع متجهات مدمجة — بلا تكاثر ETL ولا نسخ قديمة.",
      "pillar2.tag": "طبقة النماذج",
      "pillar2.title": "أي نموذج، بحوكمة كاملة",
      "pillar2.desc": "استدعِ أي نموذج لغوي كبير أو نموذج تضمين عبر واجهة واحدة، مع لقطة سياق وتتبّع شامل عند كل طلب.",
      "pillar3.tag": "طبقة الوكلاء",
      "pillar3.title": "وكلاء يتحسّنون في الإنتاج",
      "pillar3.desc": "يتعلّم وكلاء الإنتاج من التغذية الواقعية، ويحتفظون بذاكرة طويلة المدى، ويحسّنون أنفسهم خلف بوابات الانحدار — بأمان.",
      "stat1.lbl": "نسيج موحّد — قاعدة بيانات ومتجهات ونماذج &amp; وكلاء",
      "stat2.lbl": "نماذج يمكن الوصول إليها عبر واجهة واحدة",
      "stat3.lbl": "قواعد بيانات متجهية منفصلة لإدارتها",
      "stat4.lbl": "توافر عالٍ بفضل فصل التخزين",
      "cap.eyebrow": "قدرات المنصة",
      "cap.title": "منصة بيانات مصمّمة لعصر الوكلاء",
      "cap.desc": "كل ما تحتاجه لنقل تطبيقات الذكاء الاصطناعي من النموذج الأولي إلى الإنتاج — دون أن تدمج بنفسك عشرات الأنظمة.",
      "cap1.eyebrow": "OmniFabric Core · منصة البيانات",
      "cap1.title": "أساس فائق الدمج وسحابي أصيل",
      "cap1.desc": "محرّك واحد للأحمال المعامِلاتية والتحليلية، مع فصل التخزين عن الحوسبة ليتوسّع كلٌّ منهما باستقلالية وعند الطلب.",
      "cap1.li1": "<b>HTAP في محرّك واحد</b> — قدّم OLTP وOLAP من البيانات نفسها، دون مسارات تتطلّب المزامنة.",
      "cap1.li2": "<b>فصل التخزين عن الحوسبة</b> — وسّع إنتاجية الاستعلام والسعة كلٌّ على حدة.",
      "cap1.li3": "<b>بحث متجهي وتعلّم آلي مدمجان</b> — التضمينات والاستدلال بجوار بياناتك.",
      "cap1.li4": "<b>استنساخ بلا نسخ والسفر عبر الزمن</b> — فرّع مجموعات البيانات واسترجعها فورًا.",
      "cap1.link": "استكشف OmniFabric Core",
      "cap2.eyebrow": "OmniFabric Intelligence · متعدّد الوسائط",
      "cap2.title": "حوّل أي بيانات إلى سياق جاهز للذكاء الاصطناعي",
      "cap2.desc": "استوعب المصادر المهيكلة وشبه المهيكلة وغير المهيكلة، ثم حلّلها واستخرجها واربطها في قاعدة معرفة محدّثة باستمرار.",
      "cap2.li1": "<b>استيعاب موحّد</b> — قواعد البيانات والملفات وواجهات API والتدفّقات في منصة واحدة.",
      "cap2.li2": "<b>معالجة متعددة الوسائط</b> — تُحلَّل ملفات PDF والصور والفيديو وتُضمَّن تلقائيًا.",
      "cap2.li3": "<b>الرسوم المعرفية</b> — روابط دلالية تربط الكيانات عبر كل المصادر.",
      "cap2.li4": "<b>استخراج آلي</b> — فهم للمستندات يبقى محدّثًا دائمًا.",
      "cap2.link": "شاهد خطوط المعالجة متعدّدة الوسائط",
      "flow.ingest.t": "الاستيعاب",
      "flow.ingest.s": "PDF · صورة · فيديو · جداول · تدفّقات",
      "flow.parse.t": "التحليل &amp; التضمين",
      "flow.parse.s": "استخراج · تقطيع · متجهات",
      "flow.kb.t": "قاعدة المعرفة",
      "flow.kb.s": "مرتبطة دلاليًا &amp; قابلة للاستعلام",
      "cap3.eyebrow": "OmniFabric Agent · بيئة تشغيل الذكاء",
      "cap3.title": "أطلق وكلاء جديرين بالثقة في الإنتاج",
      "cap3.desc": "زمن تشغيل للوكلاء يلتقط لقطة سياق كاملة قبل كل استدعاء للنموذج، فتكون كل القرارات قابلة للتفسير والاختبار والتراجع.",
      "cap3.li1": "<b>تتبّع قابل للتدقيق للقرارات</b> — يُلتقط السياق الكامل قبل كل استدعاء للنموذج.",
      "cap3.li2": "<b>تحسين ذاتي</b> — تتحدّث المطالبات والمهارات تلقائيًا من التغذية الواقعية.",
      "cap3.li3": "<b>اختبار A/B آمن</b> — جرّب على حركة الإنتاج دون تكرار البيانات.",
      "cap3.li4": "<b>بوابات الانحدار</b> — لا يُطلق سوى التغييرات التي تجتاز معيار الجودة لديك.",
      "cap3.link": "ابنِ وكلاء موثوقين",
      "pm1.l": "استدعاءات بتتبّع نَسَب ملتقَط",
      "pm2.l": "تجارب حيّة، بلا نسخ",
      "pm3.l": "تراجع إلى نقطة زمنية",
      "pm4.l": "نجاح المهام بعد الضبط الذاتي",
      "cap4.eyebrow": "OmniFabric Memory · ذاكرة الوكلاء",
      "cap4.title": "ذاكرة طويلة المدى بضوابط مؤسسية",
      "cap4.desc": "امنح الوكلاء ذاكرة دائمة تستمرّ عبر الجلسات وتتحسّن مع الوقت — مدقّقة بالكامل ومضبوطة الوصول.",
      "cap4.li1": "<b>سياق طويل المدى</b> — احتفظ بالمعرفة عبر الجلسات والمستخدمين.",
      "cap4.li2": "<b>تعلّم تكيّفي</b> — تتحسّن الذاكرة باستمرار أثناء عمل الوكلاء.",
      "cap4.li3": "<b>مسارات تدقيق كاملة</b> — كل كتابة في الذاكرة قابلة للتتبّع والتراجع.",
      "cap4.li4": "<b>تحكّم دقيق بالوصول</b> — حوكمة قائمة على الأدوار لما يتذكّره الوكلاء.",
      "cap4.link": "أضف ذاكرة الوكلاء",
      "out.eyebrow": "عائد استثمار حقيقي",
      "out.title": "حوّل استراتيجية الذكاء الاصطناعي إلى نتائج قابلة للقياس",
      "out.desc": "عندما تتشارك البيانات والنماذج والوكلاء منصة واحدة، يكتمل عملٌ كان يستغرق أيامًا في ثوانٍ — وينعكس على النتائج المالية.",
