      "out4.title": "تجهيز عطاءات أسرع",
      "out4.desc": "عروض تُجمَّع من قاعدة المعرفة في جزء يسير من الوقت.",
      "nav.why": "لماذا نحن",
      "why.eyebrow": "لماذا OmniFabric",
      "why.title": "منصة واحدة تتفوّق على كومة من الحلول المنفصلة",
      "why.desc": "يمنحك مزوّدو السحابة الكبار خدماتٍ عديدة لتدمجها بنفسك؛ وتتوقّف المنصات التقليدية عند قاعدة البيانات. أما OmniFabric فمنصة واحدة تملكها — موحّدة وسيادية واقتصادية وذاتية التحسّن.",
      "adv1.title": "الكل في واحد",
      "adv1.desc": "البيانات والمتجهات والنماذج والوكلاء على منصة واحدة — بلا شيفرة ربط ولا منظومة من خمسة مزوّدين لتشغيلها.",
      "adv2.title": "السيادة",
      "adv2.desc": "انشر في سحابتك أو محليًا أو في بيئة معزولة. تبقى بياناتك ونماذجك في منطقتك وتحت سيطرتك.",
      "adv3.title": "فعّال التكلفة",
      "adv3.desc": "فاتورة واحدة، بلا رسوم نقل بين الخدمات، وبلا بنود لكل ميزة — خفضٌ كبير لإجمالي تكلفة التملّك.",
      "adv4.title": "التطوّر الذاتي",
      "adv4.desc": "يتعلّم الوكلاء من تغذية الإنتاج ويتحسّنون خلف بوابات الانحدار، فتتراكم القيمة مع الوقت.",
