      "pr.faq.a1": "لا. البحث المتجهي أصلي في OmniFabric — التضمينات بجوار بياناتك العلائقية، فتشغّل استعلامات هجينة بالكلمات المفتاحية + المتجهات في عبارة واحدة، بلا نظام إضافي تشغّله أو تدفع مقابله.",
