      "au.sso.note": "Anda akan dialihkan dengan aman ke CloudSigma untuk masuk. Dengan melanjutkan, Anda menyetujui Kebijakan Privasi dan Ketentuan Layanan kami.",
      "px.eyebrow": "Harga",
      "px.title": "Bayar sesuai pemakaian — per jam atau per bulan",
      "px.desc": "Beli node komputasi per jam secara bayar sesuai pemakaian, atau pesan bulanan, lalu tambahkan AI, penyimpanan, dan lalu lintas keluar berbasis pemakaian. Transparan, terinci dalam satu tagihan, dan tersedia di setiap region OmniFabric.",
      "px.reg.eb": "Region",
      "px.reg.h": "Tersedia di setiap region",
      "px.reg.p": "Jalankan OmniFabric dekat dengan pengguna dan regulator Anda. Data Anda diproses dan disimpan hanya di region yang Anda pilih. Harga daftar konsisten di semua region — hubungi tim penjualan untuk komitmen pemakaian dan kuota volume.",
