      "px.cn.p": "Komputasi yang dijual per node untuk menggerakkan seluruh fabric — data, model, dan agen. Atasi lonjakan dengan bayar sesuai pemakaian, atau pesan node bulanan dan hemat.",
      "px.cn.note": "Node per jam ditagih per detik tanpa komitmen — ideal untuk lonjakan, batch, dan pengembangan. Node bulanan adalah reservasi tetap dan sekitar 20% lebih murah. Penyimpanan dan data dipisah dari komputasi, jadi Anda bisa menaikkan atau menurunkan node kapan saja tanpa kehilangan status.",
