      "px.from": "mulai",
      "px.inc": "<b>Setiap node hadir dengan fabric Agen · Model · Data lengkap</b> — pencarian vektor native, kueri HTAP, tata kelola, silsilah, dan SSO. Tidak ada yang dikunci di tingkat lebih tinggi, dan semua pemakaian terukur dalam catatan yang dapat diaudit.",
      "px.usd": "Semua harga dalam USD dan belum termasuk pajak lokal. Pemakaian per jam ditagih per detik; node bulanan adalah reservasi tetap.",
      "px.faq.eb": "FAQ",
      "px.faq.h": "Pertanyaan harga, terjawab",
      "px.faq.q1": "Bulanan atau per jam — mana yang sebaiknya saya pilih?",
      "px.faq.a1": "Gunakan bayar-sesuai-pakai per jam untuk beban yang berfluktuasi, singkat, atau eksperimental — ditagih per detik tanpa komitmen. Pesan node bulanan untuk produksi yang stabil dan hemat sekitar 20%. Anda bisa menggabungkan keduanya dalam satu proyek dan memindahkan node antar mode kapan saja.",
      "px.faq.q2": "Bagaimana token AI ditagih?",
      "px.faq.a2": "Setiap panggilan model diukur berdasarkan token masukan dan keluaran serta dihargai per juta. Gunakan model yang dirutekan OmniFabric, atau kunci penyedia Anda sendiri — token diteruskan sesuai biaya penyedia tanpa markup, sambil tetap berada dalam silsilah dan tata kelola yang sama.",
      "px.faq.q3": "Apakah harga berbeda per region?",
      "px.faq.a3": "Harga daftar konsisten di ketujuh region. Data Anda diproses dan disimpan hanya di region yang Anda pilih. Untuk pemakaian berkomitmen atau bervolume tinggi di region tertentu, hubungi tim penjualan untuk penawaran khusus.",
      "px.faq.q4": "Apakah ada cara memulai gratis?",
      "px.faq.a4": "Ya — buat ruang kerja gratis, hubungkan sumber, dan luncurkan agen pertama. Anda baru mulai membayar saat menyediakan node komputasi atau memakai AI, penyimpanan, atau egress yang terukur.",
      "px.faq.q5": "Apa yang dihitung sebagai penyimpanan dan egress?",
      "px.faq.a5": "Penyimpanan adalah data yang Anda simpan di fabric — tabel, vektor, dan file — ditagih per GB-bulan. Egress adalah lalu lintas keluar dari region menuju internet publik. Membaca data Anda sendiri dan lalu lintas dalam-region gratis.",
      "px.cta.h": "Mulai gratis, skalakan saat Anda siap",
