      "demo.eb": "Demo langsung",
      "demo.h": "Lihat OmniFabric beraksi",
      "demo.p": "Sepuluh kasus penggunaan Data + AI paling umum — masing-masing dianimasikan menyeluruh, semuanya ditenagai fabric yang sama.",
      "demo.c1.t": "Dasbor analitik",
      "demo.c1.d": "KPI dan grafik langsung yang menyegar begitu data baru tiba.",
      "demo.c2.t": "Pemeliharaan prediktif",
      "demo.c2.d": "Tren sensor menandai kegagalan lebih awal dan membuat perintah kerja otomatis.",
      "demo.c3.t": "Wawasan bahasa alami",
      "demo.c3.d": "Ajukan pertanyaan dengan bahasa sehari-hari, dapatkan grafik dan jawabannya.",
