      "p.eng.eb": "Di balik layar",
      "p.eng.h": "Empat mesin yang menenagai fabric",
      "p.eng.p": "Empat mesin bekerja bersama sebagai satu platform — fondasi inteligensi data multimodal kelas enterprise yang terpadu.",
      "p.eng1.s": "Basis data cloud-native hyper-konvergen",
      "p.eng1.d": "Menyatukan OLTP dan OLAP, vektor dan pencarian, lakehouse, data terstruktur dan tak terstruktur — menenagai fondasi data multimodal kelas enterprise.",
      "p.eng2.s": "Repositori layanan model AI",
      "p.eng2.d": "Manajemen terpusat untuk model AI multi-jenis dan multi-spesifikasi — menyederhanakan onboarding dan pemeliharaan model demi aplikasi cerdas yang gesit.",
      "p.eng3.s": "Pipeline ETL data multimodal",
      "p.eng3.d": "Konektor khusus untuk ingesti dan transformasi multimodal terpadu, dengan orkestrasi visual menyeluruh untuk pemrosesan streaming yang efisien.",
      "p.eng4.s": "Agen inteligensi data",
      "p.eng4.d": "Agen pencarian data dan rekayasa data untuk data heterogen — memungkinkan pengguna membuka nilai data lewat bahasa alami.",
      "p.cm.eb": "Empat modul inti",
      "p.cm.h": "Seluruh pipeline, dari hulu ke hilir",
      "p.cm.p": "Dari ingesti hingga agen pengambilan — membangun platform inteligensi data multimodal generasi berikutnya.",
      "p.cm1.t": "Ingesti, penyimpanan &amp; pengindeksan terpadu",
      "p.cm1.f1": "<b>Integrasi sumber data</b> — konektor multi-sumber untuk data terstruktur, semi-terstruktur, dan tak terstruktur.",
      "p.cm1.f2": "<b>Ingesti otomatis</b> — muatan historis dan inkremental dengan kelengkapan dan kesegaran real-time.",
      "p.cm2.t": "Parsing &amp; ekstraksi multimodal",
      "p.cm2.f1": "<b>Parsing dokumen kompleks</b> — ekstrak informasi terstruktur dengan berbagai strategi parsing, chunking, dan vektorisasi.",
      "p.cm2.f2": "<b>Parsing multimedia</b> — gambar, audio, dan video dengan dukungan model yang dapat dipertukarkan.",
      "p.cm3.t": "Alur pemrosesan data yang fleksibel",
      "p.cm3.f1": "<b>Operator bawaan</b> — node parsing, pembersihan, dan augmentasi siap pakai, plus dukungan node kustom.",
      "p.cm3.f2": "<b>Orkestrasi visual</b> — konfigurasi alur kerja berbasis DAG untuk penyiapan pipeline yang cepat.",
      "p.cm4.t": "Agen pengambilan &amp; analitik data",
      "p.cm4.f1": "<b>Agen tanya-jawab data</b> — kueri bahasa alami di data terstruktur dan tak terstruktur, dengan agregasi dan drill-down.",
      "p.cm4.f2": "<b>Keterlacakan rantai penuh</b> — jawaban mencakup silsilah lengkap sumber, penalaran, dan langkah eksekusi.",
      "p.sec.eb": "Kelas enterprise",
      "p.sec.h": "Keamanan &amp; kontrol akses, sudah terpasang",
      "p.sec1.t": "Kontrol akses RBAC",
      "p.sec1.d": "Manajemen granular atas pengguna, peran, izin fitur, dan akses data — hingga ke tingkat kolom.",
      "p.sec2.t": "Isolasi multi-tenant",
      "p.sec2.d": "Tenant ruang kerja terisolasi dengan penyimpanan dan komputasi khusus, sehingga tim dan data tak pernah saling bocor antar batas.",
      "p.sec3.t": "Silsilah &amp; jejak audit",
      "p.sec3.d": "Setiap transformasi dan keputusan agen dapat ditelusuri menyeluruh — siap audit untuk GDPR, SOC 2, dan kebijakan Anda sendiri.",
      "p.dep.eb": "Terapkan sesuai cara Anda",
      "p.dep.h": "Penerapan privat atau cloud terkelola",
      "p.dep1.t": "Penerapan privat",
      "p.dep1.f1": "Lingkungan privat terisolasi — data sepenuhnya dalam kendali Anda.",
      "p.dep1.f2": "Jaringan privat berkinerja tinggi — tanpa latensi internet publik.",
      "p.dep1.f3": "Sekali terapkan, pakai jangka panjang, biaya yang terprediksi.",
      "p.dep1.cta": "Hubungi kami",
      "p.dep2.t": "Layanan cloud",
      "p.dep2.f1": "Siap pakai — luncurkan aplikasi AI dengan cepat.",
      "p.dep2.f2": "Skala elastis, fleksibilitas bayar sesuai pemakaian.",
      "p.dep2.f3": "Pembaruan berkelanjutan — selalu fitur terbaru.",
      "p.dep2.cta": "Mulai uji coba gratis",
