      "ab.eyebrow": "Tentang OmniFabric",
      "ab.title": "Dibangun di atas fondasi teruji dalam cloud berdaulat dan data AI-native",
      "ab.desc": "OmniFabric menggabungkan dua fondasi teruji — infrastruktur cloud berdaulat dan platform data AI-native — menjadi satu platform untuk data dan AI.",
      "ab.mission.eyebrow": "Misi kami",
      "ab.mission.title": "Jadikan AI tepercaya sebagai default — di atas infrastruktur yang Anda kendalikan",
      "ab.mission.p": "Setiap organisasi seharusnya dapat menjalankan AI produksi di atas data miliknya, dengan keputusan yang dapat diaudit. OmniFabric menggabungkan cloud berdaulat dengan platform data AI-native, sehingga tim meluncurkan agen tepercaya tanpa melepaskan kendali atas data mereka.",
      "ab.cs.tag": "Warisan cloud",
      "ab.cs.title": "Infrastruktur cloud yang berdaulat dan fleksibel",
      "ab.cs.p1": "Didirikan pada 2009 di Zürich, Swiss oleh Robert Jenkin dan Patrick Baillie, CloudSigma memelopori IaaS murni di mana pelanggan menentukan infrastrukturnya sendiri tanpa batasan artifisial.",
      "ab.cs.p2": "Beroperasi dari Zurich, Las Vegas, dan Washington serta melayani lebih dari 75.000 pelanggan, CloudSigma menghadirkan Cloud-as-a-Service yang aman, berkelanjutan, dan berdaulat — kini juga Intelligence-as-a-Service.",
      "ab.cs.f1l": "Didirikan",
      "ab.cs.f2l": "Kantor pusat",
      "ab.cs.f2v": "Zürich, Swiss",
      "ab.cs.f3l": "Pelanggan",
      "ab.cs.f4l": "Jangkauan",
      "ab.cs.link": "Kunjungi cloudsigma.com",
      "ab.mo.tag": "Warisan Data &amp; AI",
      "ab.mo.title": "Platform inteligensi data AI-native",
      "ab.mo.p1": "Didirikan pada 2021 dengan tim di Shanghai, Shenzhen, Beijing, dan Bay Area, MatrixOrigin membangun MatrixOne — basis data HTAP yang AI-native dan kompatibel MySQL dengan kontrol versi Git-for-Data serta pencarian vektor dan teks lengkap bawaan.",
      "ab.mo.p2": "Mesin hyper-konvergennya menyatukan beban kerja transaksional, analitis, vektor, dan teks lengkap dalam satu sistem — tanpa ETL — dipadukan dengan MatrixOne Intelligence, platform Data + AI satu pintu.",
      "ab.mo.f1l": "Didirikan",
      "ab.mo.f2l": "Kantor",
      "ab.mo.f3l": "Mesin",
      "ab.mo.f3v": "HTAP hyper-konvergen",
      "ab.mo.f4l": "Data",
      "ab.mo.f4v": "Git-for-Data + vektor",
      "ab.mo.link": "Kunjungi matrixorigin.io",
      "ab.together.eyebrow": "Mengapa ini penting",
      "ab.together.title": "Dua fondasi, satu fabric",
      "ab.together.p": "OmniFabric memadukan cloud CloudSigma yang berdaulat dan fleksibel dengan platform data AI-native MatrixOrigin — memberi Anda data dan AI serba-satu di atas infrastruktur yang Anda kendalikan.",
      "ab.tg1.t": "Berdaulat sejak desain",
      "ab.tg1.d": "Jalankan di cloud Anda, on-prem, atau air-gapped — data Anda tetap di wilayah Anda, dalam kendali Anda.",
      "ab.tg2.t": "Serba satu",
      "ab.tg2.d": "Data, vektor, model, dan agen dalam satu platform, bukan tumpukan layanan yang harus dijahit.",
      "ab.tg3.t": "Terbuka &amp; fleksibel",
      "ab.tg3.d": "Kompatibel MySQL, SQL, dan API terbuka — tentukan infrastruktur Anda sesuai keinginan, tanpa lock-in.",
      "ab.cta.title": "Lihat apa yang bisa dilakukan satu fabric",
      "ab.cta.desc": "Jelajahi platform, atau bicarakan dengan tim kami soal menyatukan data dan AI yang berdaulat.",
      "ab.cta.b1": "Jelajahi platform",
      "ab.cta.b2": "Bicara dengan kami",
      "prod.eyebrow": "Platform",
      "prod.title": "Satu fabric hyper-konvergen untuk data, model &amp; agen",
      "prod.desc": "Semua yang dipadukan OmniFabric — fondasi data cloud-native, inteligensi multimodal, runtime agen tepercaya, memori jangka panjang, dan wilayah berdaulat yang Anda kendalikan.",
      "hero.badge.pill": "BARU",
      "hero.badge.text": "Runtime agen dan memori jangka panjang kini tersedia umum",
      "hero.title": "Kuasai data Anda.<br><span class=\"grad\">Berdayakan AI Anda.</span>",
      "hero.lead": "OmniFabric menyatukan data, model, dan agen Anda di satu platform — sehingga setiap keputusan AI berjalan di atas data tepercaya, terkelola, dan real-time, bukan salinan basi.",
      "hero.cta1": "Mulai bangun gratis",
      "hero.cta2": "Jelajahi platform",
      "hero.trust": "Dipercaya oleh tim data dan AI yang menjalankan agen di produksi",
      "fw.sub": "Inteligensi",
      "fw.title": "Flywheel",
      "node.agent": "Agen",
      "node.model": "Model",
      "node.data": "Data",
      "hero.float1": "Pencarian vektor native",
      "hero.float2": "Silsilah keputusan terekam",
      "logos.title": "Satu fabric untuk stack data &amp; AI modern",
      "pillars.eyebrow": "Roda gila inteligensi",
      "pillars.title": "Agen, model, dan data di satu platform terpadu",
      "pillars.desc": "Sebagian besar tim memasang basis data vektor, gateway model, dan lapisan orkestrasi di atas basis data lama. OmniFabric mengonsolidasikan semuanya menjadi satu platform hyper-konvergen, sehingga tiap lapisan saling memperkuat.",
      "pillar1.tag": "Lapisan data",
      "pillar1.title": "Satu sumber kebenaran",
      "pillar1.desc": "Mesin cloud-native hyper-konvergen yang menjalankan beban kerja transaksional dan analitis bersama, dengan vektor bawaan — tanpa ETL berlebihan, tanpa replika basi.",
      "pillar2.tag": "Lapisan model",
      "pillar2.title": "Model apa pun, sepenuhnya terkelola",
      "pillar2.desc": "Panggil LLM atau model embedding apa pun melalui satu antarmuka, dengan snapshot konteks dan silsilah menyeluruh terekam di setiap permintaan.",
      "pillar3.tag": "Lapisan agen",
      "pillar3.title": "Agen yang makin baik di produksi",
      "pillar3.desc": "Agen produksi belajar dari umpan balik dunia nyata, mempertahankan memori jangka panjang, dan memperbaiki diri di balik gerbang regresi — dengan aman.",
      "stat1.lbl": "Fabric terpadu — DB, vektor, model &amp; agen",
      "stat2.lbl": "Model dijangkau melalui satu API",
      "stat3.lbl": "basis data vektor terpisah untuk dijalankan",
      "stat4.lbl": "Ketersediaan dengan penyimpanan terdekopling",
      "cap.eyebrow": "Kapabilitas platform",
      "cap.title": "Platform data yang dibangun untuk era agen",
      "cap.desc": "Semua yang Anda butuhkan untuk membawa aplikasi AI dari prototipe ke produksi — tanpa mengintegrasikan sendiri setengah lusin sistem.",
      "cap1.eyebrow": "OmniFabric Core · Platform Data",
      "cap1.title": "Fondasi cloud-native yang hyper-konvergen",
      "cap1.desc": "Satu mesin untuk beban kerja transaksional dan analitis, dengan penyimpanan dan komputasi terdekopling sehingga masing-masing menskala mandiri sesuai permintaan.",
      "cap1.li1": "<b>HTAP dalam satu mesin</b> — sajikan OLTP dan OLAP dari data yang sama, tanpa pipeline yang harus disinkronkan.",
      "cap1.li2": "<b>Penyimpanan dan komputasi terdekopling</b> — skalakan throughput kueri dan kapasitas secara mandiri.",
      "cap1.li3": "<b>Pencarian vektor dan ML bawaan</b> — embedding dan inferensi berada di samping data Anda.",
      "cap1.li4": "<b>Kloning zero-copy dan time travel</b> — cabangkan dan kembalikan dataset secara instan.",
      "cap1.link": "Jelajahi OmniFabric Core",
      "cap2.eyebrow": "OmniFabric Intelligence · Multimodal",
      "cap2.title": "Ubah data apa pun menjadi konteks siap-AI",
      "cap2.desc": "Ingesti sumber terstruktur, semi-terstruktur, dan tak terstruktur, lalu urai, ekstrak, dan tautkan menjadi basis pengetahuan yang terus diperbarui.",
      "cap2.li1": "<b>Ingesti terpadu</b> — basis data, file, API, dan stream mendarat di satu platform.",
      "cap2.li2": "<b>Pemrosesan multimodal</b> — PDF, gambar, dan video diurai dan di-embed otomatis.",
      "cap2.li3": "<b>Knowledge graph</b> — tautan semantik menghubungkan entitas di setiap sumber.",
      "cap2.li4": "<b>Ekstraksi otomatis</b> — pemahaman dokumen yang selalu mutakhir.",
      "cap2.link": "Lihat pipeline multimodal",
